export const tldrZh: Record<string, string> = {
  "aml-flt3": "FLT3突变型急性髓系白血病携带一个生长信号受体的突变，使白血病迅速复发。在化疗基础上加用FLT3抑制剂（米哚妥林或奎扎替尼）可延长生命，疾病复发时吉瑞替尼是标准治疗。",
  "aml-idh": "IDH突变型急性髓系白血病有一个异常的代谢酶，使细胞充满一种阻止成熟的化学物质。关闭该酶的口服药，IDH1用艾伏尼布或奥卢他西尼（olutasidenib），IDH2用恩西地平，可让白血病细胞成熟；艾伏尼布联合阿扎胞苷使老年患者的总生存期延长至原来的三倍。",
  "aml-npm1-kmt2a": "NPM1突变型和KMT2A重排型白血病依赖一种叫menin的蛋白来维持白血病基因的开启。Menin抑制剂瑞米尼布（revumenib）和齐夫托尼布（ziftomenib）是首批利用这一点的药物，能在其他治疗全部失败后的患者中带来缓解。",
  "aml-secondary": "继发性急性髓系白血病由先前的骨髓疾病演变而来，或在为另一种癌症进行化疗或放疗之后发生。它比其他白血病对标准治疗更耐药；两种经典化疗药的脂质体制剂CPX-351可延长体能较好的老年患者的生命，而移植是唯一的治愈途径。",
  "apl": "急性早幼粒细胞白血病由一个融合基因引起，它将血细胞冻结在不成熟阶段并引发危险的出血。两种非化疗药物，维生素A衍生物和三氧化二砷，能使细胞成熟，治愈超过九成患者。",
  "aml-older-unfit": "大多数急性髓系白血病患者超过65岁，许多人无法承受强化化疗。维奈克拉联合阿扎胞苷这两种较温和的药物使这一人群的缓解率翻倍并延长了生命，取代了过去在支持治疗和低剂量化疗之间的选择。",
  "smouldering-myeloma": "冒烟型骨髓瘤是尚未损害骨骼、肾脏或血细胞计数的骨髓瘤。大多数人接受观察，但进展风险高的患者现在可以治疗：AQUILA试验显示单用达雷妥尤单抗可延缓活动性骨髓瘤，并于2025年获批用于这一用途。",
  "myeloma-transplant-eligible": "体能较好的新诊断骨髓瘤患者同时接受四种药物，然后采集自身干细胞，接受高剂量化疗，回输细胞并继续维持治疗。在三药基础方案上加用CD38抗体达雷妥尤单抗（PERSEUS和CASSIOPEIA试验）意味着大多数患者现在能达到检测不到骨髓瘤的状态。",
  "myeloma-transplant-ineligible": "大多数新诊断骨髓瘤患者因年龄或体弱而不能接受干细胞移植。将CD38抗体与来那度胺和地塞米松联用（MAIA），对较健康者再加硼替佐米（IMROZ），现在能使许多患者的疾病控制约五年并延长生命。",
  "myeloma-relapsed-refractory": "骨髓瘤几乎总会复发，而每次复发都更难治疗。针对骨髓瘤细胞上BCMA蛋白的两类免疫治疗，CAR-T细胞（KarMMa-3、CARTITUDE-4）和现货型双特异性抗体（MajesTEC），现在能在其他药物失败后带来深度缓解，第二个靶点GPRC5D又提供了另一种选择。",
  "plasma-cell-leukaemia": "浆细胞白血病是癌变的浆细胞大量进入血流的骨髓瘤。它是最具侵袭性的浆细胞肿瘤，需要紧急同时使用多种骨髓瘤药物，随后进行干细胞移植。",
  "mds-lower-risk": "较低危骨髓增生异常综合征很少迅速转变为白血病；问题在于贫血及其所需的输血。促红细胞生成素，继而是罗特西普（COMMANDS）和端粒酶抑制剂伊美司他（IMerge），使许多患者数月甚至数年不需输血，来那度胺对del(5q)亚型也有同样效果。",
  "mds-higher-risk": "较高危骨髓增生异常综合征表现如同缓慢的白血病，并常常转变为白血病。阿扎胞苷可延长生命，供者干细胞移植是唯一的治愈方法；迄今所有在大型试验中试图超越阿扎胞苷的尝试，包括VERONA中测试的维奈克拉联合方案，都以失败告终。",
  "cll-treatment-naive": "慢性淋巴细胞白血病只在引起问题时才治疗，化疗已被淘汰。首次治疗现在是无限期服用BTK抑制剂，或为期一年的维奈克拉联合奥妥珠单抗（CLL14），两者也可联合作为固定疗程。",
  "cll-relapsed": "慢性淋巴细胞白血病复发时，通常的做法是更换药物类别：BTK抑制剂后改用维奈克拉方案，或维奈克拉后改用BTK抑制剂。匹妥布替尼（BRUIN）在旧的BTK抑制剂失效后仍然有效，CAR-T已获批用于两类药物都已用尽的患者。",
  "richter-transformation-cll": "Richter转化是缓慢的慢性淋巴细胞白血病突然转变为快速生长的淋巴瘤，通常为弥漫大B细胞型。治疗采用淋巴瘤化疗，可能时随后进行供者移植；由于标准化疗很少能治愈，匹妥布替尼、维奈克拉联合方案和双特异性抗体等新药正在测试中。",
  "cml-chronic-phase": "慢性期慢性髓系白血病是伊马替尼使其从致命变为可控的疾病：每日一片药物阻断驱动它的BCR::ABL1蛋白。血液检测能把白血病基因追踪到百万分之一，阿思尼布（ASC4FIRST）等新药更快达到更深的缓解，多年检测不到疾病的患者可以尝试停药。",
  "cml-advanced-phase": "慢性髓系白血病可以加速，然后转变为称为急变期的急性白血病。酪氨酸激酶抑制剂以全剂量给予，急变期还联合急性白血病化疗，以尽快使疾病回到慢性期，从而接受供者干细胞移植，这是唯一能治愈它的治疗。",
  "primary-myelofibrosis": "原发性骨髓纤维化是一种骨髓被瘢痕取代、脾脏肿大、患者贫血和极度疲乏的血液癌症。JAK抑制剂，先是芦可替尼（COMFORT），随后是菲卓替尼、帕克替尼和莫洛替尼（MOMENTUM），能缩小脾脏并缓解症状；只有供者干细胞移植能治愈它。",
};
